contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We call transfer on c with arbitrary inputs. The rule: when transfer returns (does not revert), it returns true.
    // Additionally, calling transfer does not change the InvMutTest contract's Ether balance (c does not send Ether back).
    function run(address contract_address, address[] memory tos, uint[] memory vs) public payable {
        require(contract_address != address(0) && contract_address != address(c));
        // precondition: arrays non-empty and same length to reach the main loop in C.transfer
        require(tos.length > 0 && vs.length > 0 && tos.length == vs.length);

        uint beforeBalance = address(this).balance;
        bool reverted;
        bool ret;
        // call and capture revert/return
        try c.transfer(contract_address, tos, vs) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // If not reverted, transfer must have returned true and our balance unchanged.
        assert(reverted || (ret == true && address(this).balance == beforeBalance));
    }

    receive() external payable {}
}

